VAR
    Internal_Fault : BOOL;
    Fault_Reset_Trig : R_TRIG;
END_VAR

Fault_Reset_Trig(CLK := Fault_Reset);

IF Fault_Reset_Trig.Q THEN
    Internal_Fault := FALSE;
END_IF;

IF Motor_Running AND (Motor_Current > (41.5 * 1.15) OR Motor_Winding_Temp > 140.0) THEN
    Internal_Fault := TRUE;
END_IF;

Overload_Timer(IN := Motor_Running AND (Motor_Current > 41.5 OR Motor_Winding_Temp > 120.0), PT := T#0S);

IF Overload_Timer.Q THEN
    Internal_Fault := TRUE;
END_IF;

Overload_Alarm := Motor_Running AND (Motor_Current > 41.5 OR Motor_Winding_Temp > 120.0);
Motor_Stop := Internal_Fault OR NOT Start_Command;

